import type {
  UCATOptionKey,
  UCATQuestion,
  UCATQuestionTag,
  UCATSubtypeId,
} from "./ucatQuestionBank";

const OPTION_KEYS: UCATOptionKey[] = ["A", "B", "C", "D"];

const TFC_OPTIONS = [
  { key: "A" as const, text: "True" },
  { key: "B" as const, text: "False" },
  { key: "C" as const, text: "Can't tell" },
];

function pad(index: number, width = 4) {
  return String(index + 1).padStart(width, "0");
}

function buildOptions(
  correctText: string,
  distractors: [string, string, string],
  seed: number
) {
  const answerIndex = seed % OPTION_KEYS.length;
  const texts = [...distractors] as string[];
  texts.splice(answerIndex, 0, correctText);
  return {
    options: texts.map((text, i) => ({ key: OPTION_KEYS[i], text })),
    answer: OPTION_KEYS[answerIndex],
  };
}

type VrFourOption = {
  question: string;
  correct: string;
  distractors: [string, string, string];
  explanation: string;
};

export type VrPassageInput = {
  stimulus: string[];
  tfc: {
    statement: string;
    answer: "True" | "False" | "Can't tell";
    explanation: string;
  };
  detail: VrFourOption;
  inference: VrFourOption;
  fourth: VrFourOption & {
    type: "summary" | "author" | "negative";
  };
};

const VR_FOURTH_SUBTYPE_MAP: Record<"summary" | "author" | "negative", UCATSubtypeId> = {
  summary: "vr-summary",
  author: "vr-author",
  negative: "vr-negative",
};

const VR_FOURTH_TAG_MAP: Record<"summary" | "author" | "negative", UCATQuestionTag[]> = {
  summary: ["summary-structure", "text-stem", "set-based", "medium"],
  author: ["author-opinion", "text-stem", "set-based", "medium"],
  negative: ["negative-except", "text-stem", "set-based", "hard"],
};

function buildVrPassageQuestions(
  setId: string,
  input: VrPassageInput,
  seedBase: number
): UCATQuestion[] {
  const tfcAnswer: UCATOptionKey =
    input.tfc.answer === "True" ? "A" : input.tfc.answer === "False" ? "B" : "C";

  const { options: detailOpts, answer: detailAns } = buildOptions(
    input.detail.correct,
    input.detail.distractors,
    seedBase + 1
  );
  const { options: inferOpts, answer: inferAns } = buildOptions(
    input.inference.correct,
    input.inference.distractors,
    seedBase + 2
  );
  const { options: fourthOpts, answer: fourthAns } = buildOptions(
    input.fourth.correct,
    input.fourth.distractors,
    seedBase + 3
  );

  return [
    {
      id: `${setId}-1`,
      section: "vr",
      subtype: "vr-tfc",
      setId,
      tags: ["true-false-cant-tell", "text-stem", "set-based", "easy"],
      title: "Verbal Reasoning Practice",
      leftTitle: "Passage",
      stimulus: input.stimulus,
      question: input.tfc.statement,
      options: TFC_OPTIONS,
      answer: tfcAnswer,
      explanation: input.tfc.explanation,
    },
    {
      id: `${setId}-2`,
      section: "vr",
      subtype: "vr-detail",
      setId,
      tags: ["detail-retrieval", "text-stem", "set-based", "easy", "quick"],
      title: "Verbal Reasoning Practice",
      leftTitle: "Passage",
      stimulus: input.stimulus,
      question: input.detail.question,
      options: detailOpts,
      answer: detailAns,
      explanation: input.detail.explanation,
    },
    {
      id: `${setId}-3`,
      section: "vr",
      subtype: "vr-inference",
      setId,
      tags: ["inference-question", "text-stem", "set-based", "medium"],
      title: "Verbal Reasoning Practice",
      leftTitle: "Passage",
      stimulus: input.stimulus,
      question: input.inference.question,
      options: inferOpts,
      answer: inferAns,
      explanation: input.inference.explanation,
    },
    {
      id: `${setId}-4`,
      section: "vr",
      subtype: VR_FOURTH_SUBTYPE_MAP[input.fourth.type],
      setId,
      tags: VR_FOURTH_TAG_MAP[input.fourth.type],
      title: "Verbal Reasoning Practice",
      leftTitle: "Passage",
      stimulus: input.stimulus,
      question: input.fourth.question,
      options: fourthOpts,
      answer: fourthAns,
      explanation: input.fourth.explanation,
    },
  ];
}

